"use client";

import {
	IconArrowRight,
	IconBell,
	IconBellFilled,
	IconBolt,
	IconBoltFilled,
	IconBookmark,
	IconBookmarkFilled,
	IconCamera,
	IconCircleCheckFilled,
	IconClock,
	IconCloud,
	IconCloudFilled,
	IconDownload,
	IconEyeFilled,
	IconFlag,
	IconFlagFilled,
	IconFolder,
	IconFolderFilled,
	IconHeart,
	IconHeartFilled,
	IconHome,
	IconHomeFilled,
	IconMail,
	IconMapPin,
	IconMapPinFilled,
	IconMoon,
	IconMoonFilled,
	IconPlayerPlayFilled,
	IconPlus,
	IconRocket,
	IconSettings,
	IconSettingsFilled,
	IconSparkles,
	IconStar,
	IconStarFilled,
	IconSun,
	IconSunFilled,
	IconThumbUp,
	IconThumbUpFilled,
	IconTrash,
	IconTrashFilled,
} from "@tabler/icons-react";
import { useTheme } from "next-themes";
import { useEffect } from "react";

import { Badge } from "../../ui/badge";
import { Button } from "../../ui/button";

// Dev-only playground for tweaking packages/ui button + badge styles.
// Press T anywhere on the page to flip light/dark.

type IconComponent = typeof IconStar;
type NonEmptyIconPool = readonly [IconComponent, ...IconComponent[]];

const OUTLINED: NonEmptyIconPool = [
	IconStar,
	IconHeart,
	IconPlus,
	IconArrowRight,
	IconDownload,
	IconSettings,
	IconTrash,
	IconBolt,
	IconBell,
	IconBookmark,
	IconCamera,
	IconClock,
	IconCloud,
	IconFlag,
	IconFolder,
	IconHome,
	IconMail,
	IconMapPin,
	IconMoon,
	IconSun,
	IconRocket,
	IconSparkles,
	IconThumbUp,
];

const FILLED: NonEmptyIconPool = [
	IconStarFilled,
	IconHeartFilled,
	IconBellFilled,
	IconBookmarkFilled,
	IconBoltFilled,
	IconCircleCheckFilled,
	IconTrashFilled,
	IconSettingsFilled,
	IconPlayerPlayFilled,
	IconFlagFilled,
	IconFolderFilled,
	IconHomeFilled,
	IconMoonFilled,
	IconSunFilled,
	IconCloudFilled,
	IconMapPinFilled,
	IconEyeFilled,
	IconThumbUpFilled,
];

// Deterministic "random" assignment so server and client render the same
// markup (Math.random would break hydration). Each slot index gets a varied
// icon, alternates filled/outlined, and flips between leading/trailing.
function pick(i: number) {
	const filled = i % 2 === 1;
	const pool = filled ? FILLED : OUTLINED;
  const Icon = pool[(i * 7 + 3) % pool.length] ?? pool[0];
	const leading = i % 3 !== 1;
	return { Icon, leading };
}

const BUTTON_VARIANTS = [
	"default",
	"outline",
	"secondary",
	"ghost",
	"ghost-destructive",
	"destructive",
	"link",
] as const;

const BUTTON_SIZES = ["xs", "sm", "default", "lg"] as const;

const BADGE_VARIANTS = [
	"default",
	"secondary",
	"destructive",
	"green",
	"blue",
	"amber",
	"orange",
	"emerald",
	"rose",
	"violet",
	"outline",
] as const;

const BADGE_SIZES = ["md", "lg"] as const;

function useThemeHotkey() {
	const { resolvedTheme, setTheme } = useTheme();

	useEffect(() => {
		const onKey = (e: KeyboardEvent) => {
			if (e.key.toLowerCase() !== "t" || e.metaKey || e.ctrlKey || e.altKey)
				return;
			const target = e.target;
			if (
				target instanceof HTMLElement &&
				(target.isContentEditable ||
					["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName))
			)
				return;
			setTheme(resolvedTheme === "dark" ? "light" : "dark");
		};
		window.addEventListener("keydown", onKey);
		return () => window.removeEventListener("keydown", onKey);
	}, [resolvedTheme, setTheme]);
}

function Row({
	label,
	children,
}: {
	label: string;
	children: React.ReactNode;
}) {
	return (
		<div className="flex items-center gap-3">
			<span className="w-36 shrink-0 font-mono text-xs text-muted-foreground">
				{label}
			</span>
			<div className="flex flex-wrap items-center gap-2">{children}</div>
		</div>
	);
}

export function ButtonsBadgesPlaygroundBlock() {
	useThemeHotkey();

	// Monotonic slot counter across the whole page so no two adjacent
	// buttons/badges draw the same icon.
	let slot = 0;

	return (
		<main className="mx-auto max-w-4xl space-y-12 px-6 py-12">
			<div>
				<h1 className="text-lg font-semibold">Buttons & badges playground</h1>
				<p className="text-sm text-muted-foreground">
					Press <kbd className="rounded border px-1 font-mono text-xs">T</kbd>{" "}
					to toggle the theme
				</p>
			</div>

			<section className="space-y-4">
				<h2 className="text-sm font-semibold text-muted-foreground">Buttons</h2>
				<div className="space-y-3">
					{BUTTON_VARIANTS.map((variant) => (
						<Row key={variant} label={variant}>
							{BUTTON_SIZES.map((size) => {
								const { Icon, leading } = pick(slot++);
								return (
									<Button key={size} variant={variant} size={size}>
										{leading && <Icon />}
										Button
										{!leading && <Icon />}
									</Button>
								);
							})}
						</Row>
					))}
				</div>
			</section>

			<section className="space-y-4">
				<h2 className="text-sm font-semibold text-muted-foreground">Badges</h2>
				<div className="space-y-3">
					{BADGE_VARIANTS.map((variant) => (
						<Row key={variant} label={variant}>
							{BADGE_SIZES.map((size) => {
								const { Icon, leading } = pick(slot++);
								return (
									<Badge key={size} variant={variant} size={size}>
										{leading && <Icon />}
										Badge
										{!leading && <Icon />}
									</Badge>
								);
							})}
						</Row>
					))}
				</div>
			</section>
		</main>
	);
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/lib/utils.ts; derived here under Apache-2.0.
 */
export { cn } from "cn";

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { type VariantProps, cva } from "class-variance-authority";
import * as React from "react";

import { cn } from "../lib/utils";

const badgeVariants = cva(
	"group/badge inline-flex w-fit rounded-full shrink-0 items-center justify-center capitalize overflow-hidden font-medium whitespace-nowrap transition-all focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&_svg]:shrink-0",
	{
		variants: {
			variant: {
				default:
					"bg-primary text-primary-foreground shadow-[var(--custom-shadow-primary)] [a]:hover:bg-primary/80",
				secondary:
					"bg-secondary shadow-(--custom-shadow-secondary) text-secondary-foreground [a]:hover:bg-secondary/80",
				destructive:
					"bg-destructive/10 text-destructive shadow-(--custom-shadow-destructive) focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:focus-visible:ring-destructive/40 [a]:hover:bg-destructive/20",
				green:
					"bg-green-500/10 text-green-700 shadow-[var(--custom-shadow-green)] focus-visible:ring-green-500/20 dark:bg-green-500/15 dark:text-green-300 dark:focus-visible:ring-green-500/40 [a]:hover:bg-green-500/20",
				blue: "bg-blue-500/10 text-blue-700 shadow-[var(--custom-shadow-blue)] focus-visible:ring-blue-500/20 dark:bg-blue-500/15 dark:text-blue-300 dark:focus-visible:ring-blue-500/40 [a]:hover:bg-blue-500/20",
				amber:
					"bg-amber-500/10 text-amber-700 shadow-[var(--custom-shadow-amber)] focus-visible:ring-amber-500/20 dark:bg-amber-500/15 dark:text-amber-300 dark:focus-visible:ring-amber-500/40 [a]:hover:bg-amber-500/20",
				orange:
					"bg-orange-500/10 text-orange-600 shadow-[var(--custom-shadow-orange)] focus-visible:ring-orange-500/20 dark:bg-orange-600/15 dark:text-orange-400 dark:focus-visible:ring-orange-500/40 [a]:hover:bg-orange-500/20",
				emerald:
					"bg-emerald-500/10 text-emerald-700 shadow-[var(--custom-shadow-emerald)] focus-visible:ring-emerald-500/20 dark:bg-emerald-500/15 dark:text-emerald-300 dark:focus-visible:ring-emerald-500/40 [a]:hover:bg-emerald-500/20",
				rose: "bg-rose-500/10 text-rose-700 shadow-[var(--custom-shadow-rose)] focus-visible:ring-rose-500/20 dark:bg-rose-500/15 dark:text-rose-400 dark:focus-visible:ring-rose-500/40 [a]:hover:bg-rose-500/20",
				red: "bg-red-500/10 text-red-700 shadow-[var(--custom-shadow-red)] focus-visible:ring-red-500/20 dark:bg-red-500/15 dark:text-red-400 dark:focus-visible:ring-red-500/40 [a]:hover:bg-red-500/20",
				violet:
					"bg-violet-500/10 text-violet-700 shadow-[var(--custom-shadow-violet)] focus-visible:ring-violet-500/20 dark:bg-violet-500/15 dark:text-violet-300 dark:focus-visible:ring-violet-500/40 [a]:hover:bg-violet-500/20",
				fuchsia:
					"bg-fuchsia-500/10 text-fuchsia-700 shadow-[var(--custom-shadow-fuchsia)] focus-visible:ring-fuchsia-500/20 dark:bg-fuchsia-500/15 dark:text-fuchsia-300 dark:focus-visible:ring-fuchsia-500/40 [a]:hover:bg-fuchsia-500/20",
				sky: "bg-sky-500/10 text-sky-700 shadow-[var(--custom-shadow-sky)] focus-visible:ring-sky-500/20 dark:bg-sky-500/15 dark:text-sky-300 dark:focus-visible:ring-sky-500/40 [a]:hover:bg-sky-500/20",
				outline:
					"shadow-(--custom-shadow) text-foreground [a]:hover:bg-muted [a]:hover:text-muted-foreground",
			},
			size: {
				sm: "h-4 px-1.5 gap-1 text-[10px] has-[>svg:first-child]:pl-1 has-[>svg:last-child]:pr-1 [&_svg:not([class*='size-'])]:size-2.5!",
				md: "h-5 px-2 gap-[5px] text-xs has-[>svg:first-child]:pl-1.5 has-[>svg:last-child]:pr-1.5 [&_svg:not([class*='size-'])]:size-3!",
				lg: "h-6 px-2.5 gap-1.5 text-sm has-[>svg:first-child]:pl-2 has-[>svg:last-child]:pr-2 [&_svg:not([class*='size-'])]:size-3.5!",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "md",
		},
	},
);

function Badge({
	className,
	variant = "default",
	size = "md",
	render,
	children,
	...props
}: useRender.ComponentProps<"span"> & VariantProps<typeof badgeVariants>) {
	const wrappedChildren = React.Children.map(children, (child) =>
		typeof child === "string" || typeof child === "number" ? (
			<span>{child}</span>
		) : (
			child
		),
	);

	return useRender({
		defaultTagName: "span",
		props: mergeProps<"span">(
			{
				className: cn(badgeVariants({ variant, size }), className),
				children: wrappedChildren,
			},
			props,
		),
		render,
		state: {
			slot: "badge",
			variant,
			size,
		},
	});
}

export { Badge, badgeVariants };

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { type VariantProps, cva } from "class-variance-authority";
import * as React from "react";

import { cn } from "../lib/utils";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full bg-clip-padding text-sm font-medium whitespace-nowrap transition-all hover:duration-150 outline-none select-none focus-visible:border-ring focus-visible:ring-[1.5px] focus-visible:ring-ring/50 active:scale-[0.97] disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-[1.5px] aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3.5",
  {
    variants: {
      variant: {
        default:
          "bg-neutral-800 dark:bg-neutral-100 shadow-[var(--custom-shadow-primary)] text-primary-foreground hover:bg-primary/80 dark:hover:bg-primary/90 [&_svg:not([class*='text-'])]:text-neutral-300 dark:[&_svg:not([class*='text-'])]:text-neutral-700",
        outline:
          "shadow-(--custom-outline-shadow) bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:bg-card dark:hover:bg-muted [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-400",
        secondary:
          "bg-secondary shadow-[var(--custom-shadow-secondary)] text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground dark:hover:bg-muted-foreground/25 [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-300",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-400",
        // Like `ghost` (transparent at rest), but hover tints it red — bg and
        // icon/text both shift to the destructive color. For low-emphasis
        // delete affordances that only "arm" on hover.
        "ghost-destructive":
          "hover:bg-destructive/10 hover:text-destructive text-destructive focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:hover:bg-destructive/20 dark:focus-visible:ring-destructive/40",
        destructive:
          "bg-destructive/10 shadow-[var(--custom-shadow-destructive)] text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40",
        // Underline stays rendered but transparent at rest, fading its opacity
        // in on hover — the base `transition-all` animates the decoration color.
        link: "text-foreground underline decoration-foreground/20 underline-offset-4 hover:decoration-foreground",
      },
      size: {
        xs: "h-6 gap-[4.5px] rounded-full px-2.5 text-xs in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-2 has-[>svg:last-child]:pr-2 [&_svg:not([class*='size-'])]:size-[11px]",
        sm: "h-7 gap-[5px] rounded-full px-3 in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-[9px] has-[>svg:last-child]:pr-[9px]",
        default:
          "h-8 gap-[5.5px] px-3 in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-2.5 has-[>svg:last-child]:pr-2.5",
        lg: "h-8.5 gap-1.5 px-[15px] has-[>svg:first-child]:pl-3 has-[>svg:last-child]:pr-3 [&_svg:not([class*='size-'])]:size-3.5",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-full in-data-[slot=button-group]:rounded-full [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-8 rounded-full in-data-[slot=button-group]:rounded-full",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

function Button({
  className,
  variant = "default",
  size = "default",
  children,
  nativeButton,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      // When `render` swaps in a non-button element (e.g. a Next.js
      // <Link>/<a>), it isn't a native <button>; tell Base UI so it applies the
      // right a11y semantics instead of warning. An explicit prop always wins.
      nativeButton={nativeButton ?? props.render === undefined}
      {...props}
    >
      {React.Children.map(children, (child) =>
        typeof child === "string" || typeof child === "number" ? (
          <span>{child}</span>
        ) : (
          child
        )
      )}
    </ButtonPrimitive>
  );
}

export { Button, buttonVariants };
